-- Additive operations schema. Existing CMS, revision, queue and policy data are retained.
ALTER TABLE admin_user DROP CONSTRAINT admin_user_role_check;
ALTER TABLE admin_user ADD CONSTRAINT admin_user_role_check CHECK(role IN ('owner','editor','support','analyst'));
ALTER TABLE admin_user ADD COLUMN session_version integer NOT NULL DEFAULT 1;
ALTER TABLE admin_user ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE audit_log ADD COLUMN request_id text;
ALTER TABLE audit_log ADD COLUMN outcome text NOT NULL DEFAULT 'success' CHECK(outcome IN ('success','failure'));
CREATE INDEX audit_filter ON audit_log(action,created_at DESC);
CREATE TABLE operation_receipt(event_key text PRIMARY KEY,actor text NOT NULL,operation text NOT NULL,target text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE marketing_account(id text PRIMARY KEY,provider text NOT NULL CHECK(provider IN ('SITE','GA4','GSC','NAVER_WEB','NAVER_BLOG','INSTAGRAM','THREADS','GOOGLE_ADS','META_ADS','NAVER_ADS')),name text NOT NULL,external_id text NOT NULL DEFAULT '',mode text NOT NULL DEFAULT 'manual' CHECK(mode IN ('api','manual','csv')),status text NOT NULL DEFAULT 'unconnected' CHECK(status IN ('unconnected','auth_required','collecting','healthy','partial','delayed','failed','unsupported')),timezone text NOT NULL DEFAULT 'Asia/Seoul',credential_env text,token_ciphertext text,refresh_ciphertext text,token_expires_at timestamptz,settings jsonb NOT NULL DEFAULT '{}',last_success_at timestamptz,last_attempt_at timestamptz,last_error_code text,enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE marketing_campaign(id text PRIMARY KEY,name text NOT NULL,purpose text NOT NULL,content_id text REFERENCES content(id),service_id text REFERENCES content(id),account_id text REFERENCES marketing_account(id),starts_on date,ends_on date,planned_amount numeric(18,4),currency text NOT NULL DEFAULT 'KRW',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','planned','active','completed','paused','archived')),landing_path text NOT NULL,memo text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on),CHECK(planned_amount IS NULL OR planned_amount>=0));
CREATE TABLE campaign_link(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES marketing_campaign(id),url text NOT NULL,source text NOT NULL,medium text NOT NULL,campaign text NOT NULL,content text NOT NULL DEFAULT '',term text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,url));
CREATE TABLE external_post(id text PRIMARY KEY,account_id text NOT NULL REFERENCES marketing_account(id),platform_post_id text,public_url text NOT NULL,campaign_id text REFERENCES marketing_campaign(id),content_id text REFERENCES content(id),planned_at timestamptz,published_at timestamptz,verification text NOT NULL DEFAULT 'manual' CHECK(verification IN ('manual','api')),status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','published','cancelled')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,public_url));
CREATE TABLE marketing_import(id text PRIMARY KEY,account_id text NOT NULL REFERENCES marketing_account(id),checksum text NOT NULL,mapping jsonb NOT NULL,source_name text NOT NULL,timezone text NOT NULL,currency text,status text NOT NULL DEFAULT 'preview' CHECK(status IN ('preview','committed','cancelled')),valid_rows integer NOT NULL DEFAULT 0,failed_rows integer NOT NULL DEFAULT 0,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz,UNIQUE(account_id,checksum));
CREATE TABLE metric_definition(name text PRIMARY KEY,label text NOT NULL,unit text NOT NULL,aggregation text NOT NULL CHECK(aggregation IN ('sum','period','last','ratio')),definition text NOT NULL);
CREATE TABLE metric_snapshot(id text PRIMARY KEY,account_id text NOT NULL REFERENCES marketing_account(id),report text NOT NULL,grain text NOT NULL CHECK(grain IN ('period','day','lifetime','snapshot')),window_start date NOT NULL,window_end date NOT NULL,query_version text NOT NULL,dimension_key text NOT NULL DEFAULT '',metric text NOT NULL REFERENCES metric_definition(name),value numeric(24,8),status text NOT NULL CHECK(status IN ('complete','partial','missing','unsupported','failed')),timezone text NOT NULL,currency text,source_type text NOT NULL CHECK(source_type IN ('api','manual','csv','server')),content_id text REFERENCES content(id),campaign_id text REFERENCES marketing_campaign(id),import_id text REFERENCES marketing_import(id),observed_at timestamptz NOT NULL DEFAULT now(),provider_metadata jsonb NOT NULL DEFAULT '{}',voided_at timestamptz,CHECK(window_end>=window_start),CHECK(value IS NULL OR value>=0),UNIQUE(account_id,report,grain,window_start,window_end,query_version,dimension_key,metric,source_type));
CREATE INDEX metric_window ON metric_snapshot(account_id,window_start,window_end,metric) WHERE voided_at IS NULL;
CREATE TABLE spend_entry(id text PRIMARY KEY,account_id text REFERENCES marketing_account(id),campaign_id text REFERENCES marketing_campaign(id),category text NOT NULL CHECK(category IN ('advertising','ai','tool','production')),amount numeric(18,4) NOT NULL CHECK(amount>=0),currency text NOT NULL,spent_on date NOT NULL,source_type text NOT NULL CHECK(source_type IN ('manual','api')),external_key text,description text NOT NULL DEFAULT '',voided_at timestamptz,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,external_key));
CREATE TABLE marketing_attribution(id text PRIMARY KEY,session_id text,first_campaign_id text REFERENCES marketing_campaign(id),last_campaign_id text REFERENCES marketing_campaign(id),landing_path text NOT NULL,referrer_origin text,utm_source text,utm_medium text,utm_campaign text,utm_content text,utm_term text,consent boolean NOT NULL,model text NOT NULL DEFAULT 'session_last_external',observed_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE site_measurement_config(id text PRIMARY KEY CHECK(id='site'),enabled boolean NOT NULL DEFAULT false,consent_required boolean NOT NULL DEFAULT true,notice_approved boolean NOT NULL DEFAULT false,retention_days integer NOT NULL DEFAULT 30 CHECK(retention_days BETWEEN 1 AND 90),started_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO site_measurement_config(id) VALUES('site');
CREATE TABLE site_event(id text PRIMARY KEY,event_key text NOT NULL UNIQUE,session_id text NOT NULL,event_name text NOT NULL CHECK(event_name IN ('service_view','case_view','insight_view','contact_cta_click','inquiry_form_start','inquiry_submit_success')),content_id text REFERENCES content(id),campaign_id text REFERENCES marketing_campaign(id),inquiry_id text REFERENCES inquiry(id) ON DELETE SET NULL,attribution_id text REFERENCES marketing_attribution(id),path text NOT NULL,consent boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_window ON site_event(event_name,created_at,content_id);
ALTER TABLE inquiry ADD COLUMN attribution_id text REFERENCES marketing_attribution(id);
ALTER TABLE inquiry ADD COLUMN campaign_id text REFERENCES marketing_campaign(id);
ALTER TABLE inquiry ADD COLUMN intake_type text NOT NULL DEFAULT 'online' CHECK(intake_type IN ('online','manual','test'));
ALTER TABLE inquiry ADD COLUMN self_reported_source text NOT NULL DEFAULT '';
ALTER TABLE inquiry ADD COLUMN valid boolean NOT NULL DEFAULT true;
ALTER TABLE inquiry ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE client_project ADD COLUMN inquiry_id text UNIQUE REFERENCES inquiry(id) ON DELETE SET NULL;
ALTER TABLE client_project ADD COLUMN campaign_id text REFERENCES marketing_campaign(id);
ALTER TABLE client_project ADD COLUMN attribution_id text REFERENCES marketing_attribution(id);
ALTER TABLE client_project ADD COLUMN customer_name text NOT NULL DEFAULT '';
ALTER TABLE client_project ADD COLUMN starts_on date;
ALTER TABLE client_project ADD COLUMN ends_on date;
ALTER TABLE client_project ADD COLUMN quoted_amount numeric(18,4) CHECK(quoted_amount IS NULL OR quoted_amount>=0);
ALTER TABLE client_project ADD COLUMN contracted_amount numeric(18,4) CHECK(contracted_amount IS NULL OR contracted_amount>=0);
ALTER TABLE client_project ADD COLUMN currency text NOT NULL DEFAULT 'KRW';
ALTER TABLE client_project ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE project_payment(id text PRIMARY KEY,project_id text NOT NULL REFERENCES client_project(id),event_key text NOT NULL UNIQUE,amount numeric(18,4) NOT NULL CHECK(amount>=0),currency text NOT NULL,received_on date NOT NULL,memo text NOT NULL DEFAULT '',actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_event(id text PRIMARY KEY,project_id text NOT NULL REFERENCES client_project(id),body text NOT NULL,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE support_ticket ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE media_asset ADD COLUMN storage_backend text NOT NULL DEFAULT 'legacy_db' CHECK(storage_backend IN ('legacy_db','filesystem'));
ALTER TABLE media_asset ADD COLUMN storage_key text UNIQUE;
ALTER TABLE media_asset ADD COLUMN checksum text;
ALTER TABLE media_asset ADD COLUMN description text NOT NULL DEFAULT '';
ALTER TABLE media_asset ADD COLUMN tags text[] NOT NULL DEFAULT '{}';
ALTER TABLE media_asset ADD COLUMN archived boolean NOT NULL DEFAULT false;
ALTER TABLE media_asset ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE search_observation ADD COLUMN result_status text NOT NULL DEFAULT 'confirmed' CHECK(result_status IN ('confirmed','failed','timeout','unverified'));
CREATE TABLE marketing_action(id text PRIMARY KEY,title text NOT NULL,evidence text NOT NULL,hypothesis text NOT NULL,page_path text,verification text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done','cancelled')),actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE marketing_report(id text PRIMARY KEY,window_start date NOT NULL,window_end date NOT NULL,timezone text NOT NULL,definition_version text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(window_start,window_end,definition_version));
CREATE TABLE marketing_oauth_state(state_hash text PRIMARY KEY,provider text NOT NULL,account_id text REFERENCES marketing_account(id),actor text NOT NULL,verifier_ciphertext text,redirect_uri text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE runtime_heartbeat(name text PRIMARY KEY,observed_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL,detail jsonb NOT NULL DEFAULT '{}');
ALTER TABLE generation_job DROP CONSTRAINT generation_kind;
ALTER TABLE generation_job ADD CONSTRAINT generation_kind CHECK(kind IN ('COLLECT','RECHECK','GENERATE','REWRITE','TITLE','MARKETING_SYNC','MARKETING_REPORT','SEO_CHECK'));
INSERT INTO schema_migration(version) VALUES('004');
